"use strict";

const canvas = document.querySelector("#game");
const context = canvas.getContext("2d");
const scoreElement = document.querySelector("#score");
const timeElement = document.querySelector("#time");
const messageElement = document.querySelector("#message");

const GAME_SECONDS = 120;
const keys = new Set();
const backgroundStars = Array.from({ length: 90 }, () => ({
  x: Math.random() * canvas.width,
  y: Math.random() * canvas.height,
  radius: 0.5 + Math.random() * 1.5,
  alpha: 0.25 + Math.random() * 0.7,
}));

const player = {
  x: canvas.width * 0.2,
  y: canvas.height * 0.5,
  radius: 17,
  speed: 260,
};

let dust = createDust();
let meteors = [];
let score = 0;
let elapsed = 0;
let meteorDelay = randomBetween(2.5, 5.5);
let collisionFlash = 0;
let ended = false;
let previousTime;

function randomBetween(minimum, maximum) {
  return minimum + Math.random() * (maximum - minimum);
}

function createDust() {
  return {
    x: randomBetween(45, canvas.width - 45),
    y: randomBetween(45, canvas.height - 45),
    radius: 10,
    pulse: Math.random() * Math.PI * 2,
  };
}

function createMeteor() {
  const radius = randomBetween(18, 34);
  return {
    x: canvas.width + radius,
    y: randomBetween(radius, canvas.height - radius),
    radius,
    speed: randomBetween(115, 205),
    rotation: Math.random() * Math.PI * 2,
    spin: randomBetween(-1.6, 1.6),
    hit: false,
  };
}

function circlesOverlap(first, second) {
  const dx = first.x - second.x;
  const dy = first.y - second.y;
  const totalRadius = first.radius + second.radius;
  return dx * dx + dy * dy <= totalRadius * totalRadius;
}

function updatePlayer(deltaSeconds) {
  let horizontal = 0;
  let vertical = 0;

  if (keys.has("ArrowLeft")) horizontal -= 1;
  if (keys.has("ArrowRight")) horizontal += 1;
  if (keys.has("ArrowUp")) vertical -= 1;
  if (keys.has("ArrowDown")) vertical += 1;

  if (horizontal && vertical) {
    horizontal *= Math.SQRT1_2;
    vertical *= Math.SQRT1_2;
  }

  player.x += horizontal * player.speed * deltaSeconds;
  player.y += vertical * player.speed * deltaSeconds;
  player.x = Math.max(player.radius, Math.min(canvas.width - player.radius, player.x));
  player.y = Math.max(player.radius, Math.min(canvas.height - player.radius, player.y));
}

function update(deltaSeconds, realDeltaSeconds) {
  elapsed = Math.min(GAME_SECONDS, elapsed + realDeltaSeconds);
  const remaining = Math.max(0, Math.ceil(GAME_SECONDS - elapsed));
  const minutes = Math.floor(remaining / 60);
  const seconds = String(remaining % 60).padStart(2, "0");
  timeElement.textContent = `${minutes}:${seconds}`;

  if (elapsed >= GAME_SECONDS) {
    ended = true;
    keys.clear();
    messageElement.textContent = `本局结束 · 收集星尘 ${score}`;
    messageElement.hidden = false;
    return;
  }

  updatePlayer(deltaSeconds);
  dust.pulse += deltaSeconds * 4;

  if (circlesOverlap(player, dust)) {
    score += 1;
    scoreElement.textContent = String(score);
    dust = createDust();
  }

  meteorDelay -= deltaSeconds;
  if (meteorDelay <= 0) {
    meteors.push(createMeteor());
    meteorDelay = randomBetween(2.5, 5.5);
  }

  for (const meteor of meteors) {
    meteor.x -= meteor.speed * deltaSeconds;
    meteor.rotation += meteor.spin * deltaSeconds;

    if (!meteor.hit && circlesOverlap(player, meteor)) {
      meteor.hit = true;
      collisionFlash = 0.32;
    }
  }

  meteors = meteors.filter((meteor) => meteor.x + meteor.radius > 0);
  collisionFlash = Math.max(0, collisionFlash - deltaSeconds);
}

function drawBackground() {
  context.fillStyle = "#050a25";
  context.fillRect(0, 0, canvas.width, canvas.height);

  for (const star of backgroundStars) {
    context.globalAlpha = star.alpha;
    context.fillStyle = "#dce8ff";
    context.beginPath();
    context.arc(star.x, star.y, star.radius, 0, Math.PI * 2);
    context.fill();
  }
  context.globalAlpha = 1;
}

function drawDust() {
  const glow = 3 + Math.sin(dust.pulse) * 2;
  context.save();
  context.shadowColor = "#ffe88b";
  context.shadowBlur = 15 + glow;
  context.fillStyle = "#fff2a8";
  context.translate(dust.x, dust.y);
  context.rotate(dust.pulse * 0.25);
  context.beginPath();

  for (let point = 0; point < 10; point += 1) {
    const angle = -Math.PI / 2 + point * Math.PI / 5;
    const radius = point % 2 === 0 ? dust.radius + glow : dust.radius * 0.42;
    const x = Math.cos(angle) * radius;
    const y = Math.sin(angle) * radius;
    if (point === 0) context.moveTo(x, y);
    else context.lineTo(x, y);
  }

  context.closePath();
  context.fill();
  context.restore();
}

function drawPlayer() {
  context.save();
  context.translate(player.x, player.y);
  context.shadowColor = "#6ee7ff";
  context.shadowBlur = 18;
  context.fillStyle = collisionFlash > 0 ? "#ff8f8f" : "#65dfff";
  context.beginPath();
  context.moveTo(22, 0);
  context.lineTo(-14, -13);
  context.lineTo(-8, 0);
  context.lineTo(-14, 13);
  context.closePath();
  context.fill();
  context.restore();
}

function drawMeteor(meteor) {
  context.save();
  context.translate(meteor.x, meteor.y);
  context.rotate(meteor.rotation);
  context.fillStyle = meteor.hit ? "#6d5661" : "#8c6c78";
  context.strokeStyle = "#c59aa2";
  context.lineWidth = 3;
  context.beginPath();

  for (let point = 0; point < 9; point += 1) {
    const angle = point * Math.PI * 2 / 9;
    const unevenRadius = meteor.radius * (point % 2 === 0 ? 1 : 0.78);
    const x = Math.cos(angle) * unevenRadius;
    const y = Math.sin(angle) * unevenRadius;
    if (point === 0) context.moveTo(x, y);
    else context.lineTo(x, y);
  }

  context.closePath();
  context.fill();
  context.stroke();
  context.restore();
}

function draw() {
  drawBackground();
  drawDust();
  for (const meteor of meteors) drawMeteor(meteor);
  drawPlayer();

  if (collisionFlash > 0) {
    context.fillStyle = "rgba(255, 80, 100, 0.13)";
    context.fillRect(0, 0, canvas.width, canvas.height);
  }
}

function frame(now) {
  if (previousTime === undefined) previousTime = now;
  const realDeltaSeconds = Math.max(0, (now - previousTime) / 1000);
  const movementDeltaSeconds = Math.min(realDeltaSeconds, 0.05);
  previousTime = now;

  if (!ended) update(movementDeltaSeconds, realDeltaSeconds);
  draw();
  requestAnimationFrame(frame);
}

window.addEventListener("keydown", (event) => {
  if (event.key.startsWith("Arrow")) {
    event.preventDefault();
    keys.add(event.key);
  }
});

window.addEventListener("keyup", (event) => {
  if (event.key.startsWith("Arrow")) {
    event.preventDefault();
    keys.delete(event.key);
  }
});

window.addEventListener("blur", () => keys.clear());

requestAnimationFrame(frame);
